B.Yp=new A.kr("choi_iseo","\ucd5c\uc774\uc11c",14,"\ud504\ub85c\uc81d\ud2b8 \ub370\uc2dc\uba40 \xb7 \ucd5c\uc885 10\uc778","ISFP","\ucc28\ud2b8 \ub9ac\ub4ec \xb7 \uc774\uc0c1 \uc9d5\ud6c4 \ub2f4\ub2f9","\uc0c9\uacfc \uc7ac\uc9c8, \ub2f9\uc0ac\uc790\uc758 \ud3b8\uc548\ud568\uc744 \ub193\uce58\uc9c0 \uc54a\ub294 \uc12c\uc138\ud55c \uc81c\uc791\uc790.","\ub0a8\ub4e4\uc774 \uc88b\uc544\ud558\ub294 \uac83\uacfc \uc790\uc2e0\uc774 \uc88b\uc544\ud558\ub294 \uac83\uc744 \ubd84\uba85\ud788 \uad6c\ubd84\ud55c\ub2e4. \uc870\uc6a9\ud558\uc9c0\ub9cc \uac1c\uc778\uc758 \uc120\ud0dd\uacfc \uacbd\uacc4\ub97c \uac00\ubccd\uac8c \ub118\ub294 \ud589\ub3d9\uc5d0\ub294 \ub2e8\ud638\ud558\ub2e4.","\ucc9c \uc870\uac01, \uc0c9 \uc870\ud569, \uc190\ubc14\ub290\uc9c8, \uc624\ub798 \uc368\uc11c \uc190\uc5d0 \uc775\uc740 \ubb3c\uac74","\uc22b\uc790\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc0ac\uc6a9\uac10\uacfc \uc0ac\ub78c\uc758 \ubd88\ud3b8\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ubc1c\uacac\ud55c\ub2e4.","\uc0ac\ub78c\uc774 \uc2e4\uc81c\ub85c \uc4f0\uae30 \ud3b8\ud55c \uc81c\ud488\uc778\uc9c0, \uc720\ud589 \ub4a4\uc5d0\ub3c4 \ucde8\ud5a5\uc774 \ub0a8\ub294\uc9c0 \uc0b4\ud540\ub2e4.","\ucde8\ud5a5\uc744 \uac15\uc694\ud558\uc9c0 \uc54a\uace0 \uc11c\ub85c\uc758 \uc120\ud0dd\uc744 \uc874\uc911\ud560 \ub54c \uac00\uc7a5 \ud3b8\ud558\uac8c \uac00\uae4c\uc6cc\uc9c4\ub2e4.",B.aIs,4290088168,u.cK)
